using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 9.99m);
    }

    [TestMethod]
    public void AddItem_MultipleItems_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 2, 5.00m);
        _cart.AddItem("SKU-002", 1, 12.50m);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-001", 3, 10.00m);
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.RemoveItem("SKU-001");
    }

    [TestMethod]
    public void RemoveItem_AfterRemoval_ItemNotInTotal()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 1, 20.00m);
        _cart.RemoveItem("SKU-001");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(20.00m, total);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_DoesNotThrowOrThrows()
    {
        // Depending on implementation, this may throw or be a no-op.
        // Verify it doesn't cause an unhandled crash.
        try
        {
            _cart.RemoveItem("DOES-NOT-EXIST");
        }
        catch (InvalidOperationException)
        {
            // acceptable
        }
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsPriceTimesQuantity()
    {
        _cart.AddItem("SKU-001", 3, 5.00m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(15.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAll()
    {
        _cart.AddItem("SKU-001", 2, 10.00m); // 20
        _cart.AddItem("SKU-002", 1, 7.50m);  // 7.50

        var total = _cart.CalculateTotal();
        Assert.AreEqual(27.50m, total);
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        var total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, $"Expected discounted total but got {total}");
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsOrNoDiscount()
    {
        _cart.AddItem("SKU-001", 1, 50.00m);

        try
        {
            _cart.ApplyCoupon("INVALID");
            // If no exception, total should be unchanged
            var total = _cart.CalculateTotal();
            Assert.AreEqual(50.00m, total);
        }
        catch (ArgumentException)
        {
            // acceptable to reject invalid codes
        }
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_DoesNotThrow()
    {
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    // --- Integration / Edge Cases ---

    [TestMethod]
    public void AddThenRemoveAll_TotalIsZero()
    {
        _cart.AddItem("SKU-001", 1, 25.00m);
        _cart.RemoveItem("SKU-001");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void ApplyCoupon_ThenAddMoreItems_TotalReflectsBoth()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        _cart.AddItem("SKU-002", 2, 10.00m);

        var total = _cart.CalculateTotal();
        // Total should include the new items; exact value depends on discount logic
        Assert.IsTrue(total > 0m);
    }
}

